{"command":"create","path":"/app/public/styles.css","file_text":":root {
  color-scheme: dark;
  --bg: #10141c;
  --panel: #171d28;
  --line: #2b3546;
  --muted: #98a5b8;
  --text: #e8edf4;
  --accent: #6db5ff;
  --selection: #244f7e;
