* { box-sizing: border-box; }
body { margin: 0; background: var(--bg); color: var(--text); }
header { min-height: 72px; padding: 12px 20px; display: flex; align-items: center; justify-content: space-between; gap: 20px; border-bottom: 1px solid var(--line); }
.brand { color: var(--accent); font-size: 12px; font-weight: 800; letter-spacing: .16em; text-transform: uppercase; }
h1 { display: inline; margin: 0 0 0 12px; font-size: 19px; }
.status-group { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.status-group span, .status-group strong { padding: 5px 9px; border: 1px solid var(--line); border-radius: 5px; font-size: 12px; }
#save-status.dirty { color: #ffd36d; }
#save-status.saved { color: #79dda1; }
main { padding: 14px 20px 20px; }
.toolbar { display: flex; align-items: end; gap: 8px; flex-wrap: wrap; margin-bottom: 12px; }
.toolbar label { color: var(--muted); font-size: 12px; }
button, input { border: 1px solid #3b4960; border-radius: 5px; background: #222b3a; color: var(--text); padding: 7px 10px; }
button { cursor: pointer; font-weight: 650; }
