button:disabled { cursor: not-allowed; opacity: .45; }
input { display: block; margin-top: 4px; width: 165px; }
.divider { height: 30px; border-left: 1px solid var(--line); margin: 0 3px; }
#find-status { color: var(--muted); font-size: 12px; min-width: 70px; }
