#message.info { border-color: #345d7a; background: #172a3b; color: #bce2ff; }
.workspace { display: grid; grid-template-columns: minmax(500px, 1fr) 270px; gap: 14px; }
.editor { position: relative; height: calc(100vh - 194px); min-height: 430px; overflow: auto; border: 1px solid var(--line); background: #0d1118; outline: none; cursor: text; font: 14px/21px ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; user-select: none; tab-size: 4; }
.editor:focus { border-color: var(--accent); box-shadow: 0 0 0 1px var(--accent); }
#editor-spacer { width: 1px; }
#editor-lines { position: absolute; top: 0; left: 0; min-width: 100%; }
.editor-line { position: absolute; left: 0; height: 21px; min-width: 100%; white-space: pre; }
.line-number { position: sticky; left: 0; z-index: 3; display: inline-block; width: 66px; padding-right: 12px; color: #66758b; background: #111722; text-align: right; border-right: 1px solid #252e3c; }
