aside { border: 1px solid var(--line); background: var(--panel); padding: 14px; overflow: auto; max-height: calc(100vh - 194px); }
aside h2 { margin: 0; font-size: 16px; }
.aside-help { color: var(--muted); font-size: 12px; line-height: 1.45; }
#preview-banner { padding: 9px; background: #2f2918; border: 1px solid #6b5926; border-radius: 5px; font-size: 12px; }
#preview-banner button { width: 100%; margin-top: 7px; }
#revision-list { padding-left: 23px; }
#revision-list li { margin-bottom: 11px; color: var(--muted); font-size: 12px; }
#revision-list button { display: block; margin-top: 4px; width: 100%; text-align: left; }
@media (max-width: 850px) {
  .workspace { grid-template-columns: 1fr; }
  .editor { height: 62vh; }
  aside { max-height: none; }
  header { align-items: flex-start; flex-direction: column; }
}
